const N=RAW.length/2;
const LNG=new Float32Array(N), LAT=new Float32Array(N);
for(let i=0;i<N;i++){LNG[i]=RAW[i*2];LAT[i]=RAW[i*2+1];}

// ── MARKERS (brand cities) ────────────────────────────────────
const MARKERS=[
  {lat:28.63,lng:-106.09,lbl:'CHIHUAHUA',color:'#e67111'},
  {lat:19.43,lng:-99.13,lbl:'CDMX',color:'#3195ff'},
  {lat:51.51,lng:-0.13,lbl:'LONDON',color:'#ea333f'},
  {lat:48.85,lng:2.35,lbl:'PARIS',color:'#3195ff'},
  {lat:40.71,lng:-74.01,lbl:'NYC',color:'#ea333f'},
  {lat:35.69,lng:139.69,lbl:'TOKYO',color:'#3195ff'},
  {lat:-33.87,lng:151.21,lbl:'SYDNEY',color:'#e67111'},
];
let mCount=3, showGlow=true, autoRot=true;

// ── CANVAS SETUP ──────────────────────────────────────────────
(function initGlobe(){
  const container = document.getElementById('globeWrap');
  const canvas = document.getElementById('globeCanvas');
  if(!canvas) return;
  const ctx = canvas.getContext('2d');
  const DPR = Math.min(window.devicePixelRatio||1,2);

  function getSize(){
    const w = window.innerWidth;
    if(w < 768) return Math.min(w - 40, 380);
    if(w < 1024) return 460;
    return 540;
  }

  let SIZE = getSize();
  canvas.width = SIZE*DPR;
  canvas.height = SIZE*DPR;
  canvas.style.width = SIZE+'px';
  canvas.style.height = SIZE+'px';
  ctx.scale(DPR,DPR);

  // ── STATE ────────────────────────────────────────────────────
  let R = SIZE * 0.42;
  let dotR = 1.4;
  let rotX = 0.3, rotY = -1.6, rotYv = 0; // Start on Americas
  let t = 0;

  // Expose globals for GSAP ScrollTrigger
  window.globeState = {
    get rotX(){ return rotX; },
    set rotX(v){ rotX = v; },
    get rotY(){ return rotY; },
    set rotY(v){ rotY = v; },
    get autoRot(){ return autoRot; },
    set autoRot(v){ autoRot = v; },
  };

  // ── MATH ────────────────────────────────────────────────────
  function ll2xyz(lat,lng){
    const phi=(90-lat)*Math.PI/180;
    const th=(lng+180)*Math.PI/180;
    return[-Math.sin(phi)*Math.cos(th), Math.cos(phi), Math.sin(phi)*Math.sin(th)];
  }
  function rot([x,y,z],rx,ry){
    let x2=x*Math.cos(ry)+z*Math.sin(ry);
    let z2=-x*Math.sin(ry)+z*Math.cos(ry);
    let y3=y*Math.cos(rx)-z2*Math.sin(rx);
    let z3=y*Math.sin(rx)+z2*Math.cos(rx);
    return[x2,y3,z3];
  }
  function proj([x,y,z]){
    return{px:SIZE/2+x*R, py:SIZE/2-y*R, vis:z};
  }

  // ── PRE-COMPUTE XYZ ─────────────────────────────────────────
  const XYZ=new Array(N);
  for(let i=0;i<N;i++) XYZ[i]=ll2xyz(LAT[i],LNG[i]);

  // ── DRAW ─────────────────────────────────────────────────────
  function draw(){
    ctx.clearRect(0,0,SIZE,SIZE);
    const cx=SIZE/2, cy=SIZE/2;

    // Globe base
    const bg=ctx.createRadialGradient(cx-50,cy-50,20,cx,cy,R+4);
    bg.addColorStop(0,'#0a0a12');
    bg.addColorStop(1,'#060608');
    ctx.beginPath();ctx.arc(cx,cy,R+2,0,Math.PI*2);
    ctx.fillStyle=bg;ctx.fill();

    // Atmosphere ring (brand cyan)
    if(showGlow){
      const atm=ctx.createRadialGradient(cx,cy,R-8,cx,cy,R+22);
      atm.addColorStop(0,'rgba(49,149,255,0.08)');
      atm.addColorStop(0.5,'rgba(49,149,255,0.04)');
      atm.addColorStop(1,'rgba(0,0,0,0)');
      ctx.beginPath();ctx.arc(cx,cy,R+22,0,Math.PI*2);
      ctx.fillStyle=atm;ctx.fill();
    }

    // Clip sphere
    ctx.save();
    ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.clip();

    // Sort dots
    const visible=[];
    for(let i=0;i<N;i++){
      const r=rot(XYZ[i],rotX,rotY);
      if(r[2]>0) visible.push({z:r[2],px:cx+r[0]*R,py:cy-r[1]*R});
    }
    visible.sort((a,b)=>a.z-b.z);

    // Draw dots with brand palette
    for(const v of visible){
      const alpha=0.3+v.z*0.7;
      const size=dotR*(0.4+v.z*0.75);
      ctx.beginPath();ctx.arc(v.px,v.py,size,0,Math.PI*2);
      ctx.fillStyle=`rgba(240,236,228,${alpha})`;
      ctx.fill();
    }

    // Depth vignette
    const vig=ctx.createRadialGradient(cx,cy,R*0.55,cx,cy,R);
    vig.addColorStop(0,'rgba(0,0,0,0)');
    vig.addColorStop(1,'rgba(6,6,8,0.7)');
    ctx.fillStyle=vig;ctx.fillRect(0,0,SIZE,SIZE);
    ctx.restore();

    // Markers with brand colors
    for(let i=0;i<mCount;i++){
      const m=MARKERS[i];
      const r=rot(ll2xyz(m.lat,m.lng),rotX,rotY);
      if(r[2]<0.05) continue;
      const p=proj(r);
      const alpha=0.5+r[2]*0.5;
      const pulse=(Math.sin(t*2.2+i*1.7)+1)/2;
      const mc = m.color || '#3195ff';

      // Pulse rings
      for(let k=0;k<3;k++){
        const rr=6+k*7+pulse*(4+k*2);
        const a=alpha*(0.55-k*0.16)*(1-pulse*0.4);
        ctx.beginPath();ctx.arc(p.px,p.py,rr,0,Math.PI*2);
        ctx.strokeStyle=mc.replace(')',`,${a})`).replace('rgb','rgba').replace('#','').length > 8
          ? `rgba(49,149,255,${a})` : hexToRgba(mc, a);
        ctx.lineWidth=1.2-k*0.3;
        ctx.stroke();
      }

      // Core dot
      ctx.beginPath();ctx.arc(p.px,p.py,3.8,0,Math.PI*2);
      const dg=ctx.createRadialGradient(p.px,p.py,0,p.px,p.py,3.8);
      dg.addColorStop(0,`rgba(255,255,255,${alpha})`);
      dg.addColorStop(1,hexToRgba(mc, alpha));
      ctx.fillStyle=dg;ctx.fill();

      // Glow
      if(showGlow){
        const gg=ctx.createRadialGradient(p.px,p.py,0,p.px,p.py,16);
        gg.addColorStop(0,hexToRgba(mc, alpha*0.35));
        gg.addColorStop(1,'rgba(0,0,0,0)');
        ctx.beginPath();ctx.arc(p.px,p.py,16,0,Math.PI*2);
        ctx.fillStyle=gg;ctx.fill();
      }

      // Label
      if(r[2]>0.2){
        ctx.font=`${8+r[2]*3}px 'Space Mono','Courier New'`;
        ctx.fillStyle=hexToRgba(mc, alpha*0.9);
        ctx.fillText(m.lbl,p.px+12,p.py-4);
      }
    }

    // Specular
    const spec=ctx.createRadialGradient(cx-R*0.3,cy-R*0.3,0,cx-R*0.3,cy-R*0.3,R*0.55);
    spec.addColorStop(0,'rgba(255,255,255,0.05)');
    spec.addColorStop(1,'rgba(255,255,255,0)');
    ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);
    ctx.fillStyle=spec;ctx.fill();
  }

  // ── HELPER ──────────────────────────────────────────────────
  function hexToRgba(hex, a){
    const r=parseInt(hex.slice(1,3),16);
    const g=parseInt(hex.slice(3,5),16);
    const b=parseInt(hex.slice(5,7),16);
    return `rgba(${r},${g},${b},${a})`;
  }

  // ── LOOP ─────────────────────────────────────────────────────
  function loop(){
    t+=0.016;
    if(autoRot){
      rotY+=0.003+rotYv*0.1;
      rotYv*=0.9;
    } else {
      rotYv*=0.9;
      rotY+=rotYv;
    }
    draw();
    requestAnimationFrame(loop);
  }
  loop();

  // ── DRAG ─────────────────────────────────────────────────────
  let drag=false,lx=0,ly=0;
  canvas.addEventListener('mousedown',e=>{drag=true;lx=e.clientX;ly=e.clientY;autoRot=false;});
  window.addEventListener('mouseup',()=>drag=false);
  window.addEventListener('mousemove',e=>{
    if(!drag)return;
    const dx=e.clientX-lx, dy=e.clientY-ly;
    rotYv=(dx*0.006);
    rotX+=dy*0.005;
    rotX=Math.max(-1.4,Math.min(1.4,rotX));
    rotY+=dx*0.006;
    lx=e.clientX;ly=e.clientY;
  });
  canvas.addEventListener('wheel',e=>{
    e.preventDefault();
    R=Math.max(100,Math.min(SIZE*0.48,R-e.deltaY*0.25));
    dotR=0.6+R/160;
  },{passive:false});

  // Touch
  let ltx=0,lty=0,lpd=0;
  canvas.addEventListener('touchstart',e=>{ltx=e.touches[0].clientX;lty=e.touches[0].clientY;if(e.touches.length===2)lpd=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);},{passive:true});
  canvas.addEventListener('touchmove',e=>{
    e.preventDefault();
    if(e.touches.length===2){
      const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
      R=Math.max(100,Math.min(SIZE*0.48,R+(d-lpd)*0.5));lpd=d;
    } else {
      const dx=e.touches[0].clientX-ltx, dy=e.touches[0].clientY-lty;
      rotY+=dx*0.006;rotX+=dy*0.005;
      rotX=Math.max(-1.4,Math.min(1.4,rotX));
      ltx=e.touches[0].clientX;lty=e.touches[0].clientY;
    }
  },{passive:false});

  // Resize
  window.addEventListener('resize',()=>{
    SIZE=getSize();
    R=SIZE*0.42;
    canvas.width=SIZE*DPR;canvas.height=SIZE*DPR;
    canvas.style.width=SIZE+'px';canvas.style.height=SIZE+'px';
    ctx.setTransform(DPR,0,0,DPR,0,0);
  });

  // ── SCROLL CAMERA ────────────────────────────────────────────
  // Triggered by main.js after GSAP loads
  window.initGlobeScroll = function(){
    if(typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') return;

    // Region targets: Americas → Europe → Global
    const regions = [
      { rotY: -1.6, rotX: 0.3 },  // Americas (Chihuahua / CDMX)
      { rotY: 0.05, rotX: 0.2 },  // Europe (London / Paris)
      { rotY: 1.2,  rotX: 0.1 },  // Asia-Pacific (Global)
    ];

    ScrollTrigger.create({
      trigger: '#world',
      start: 'top bottom',
      end: 'bottom top',
      scrub: 1.5,
      onUpdate: (self) => {
        const p = self.progress;
        // 0→0.4: Americas→Europe, 0.4→1: Europe→Global
        let target;
        if(p < 0.45){
          const t2 = p / 0.45;
          target = {
            rotY: regions[0].rotY + (regions[1].rotY - regions[0].rotY)*t2,
            rotX: regions[0].rotX + (regions[1].rotX - regions[0].rotX)*t2,
          };
          mCount = t2 > 0.3 ? 3 : 2;
        } else {
          const t2 = (p - 0.45) / 0.55;
          target = {
            rotY: regions[1].rotY + (regions[2].rotY - regions[1].rotY)*t2,
            rotX: regions[1].rotX + (regions[2].rotX - regions[1].rotX)*t2,
          };
          mCount = 5;
        }
        // Smooth lerp
        rotY += (target.rotY - rotY) * 0.08;
        rotX += (target.rotX - rotX) * 0.08;
        autoRot = false;
      }
    });

    // Nav dots
    document.querySelectorAll('.world__nav-dot').forEach((btn, i) => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.world__nav-dot').forEach(b=>b.classList.remove('world__nav-dot--active'));
        btn.classList.add('world__nav-dot--active');
        gsap.to({rotY, rotX}, {
          rotY: regions[i].rotY,
          rotX: regions[i].rotX,
          duration: 1.8,
          ease: 'power3.inOut',
          onUpdate: function(){
            rotY = this.targets()[0].rotY;
            rotX = this.targets()[0].rotX;
          }
        });
        mCount = [2, 4, 7][i];
        autoRot = false;
      });
    });
  };

})();
